"""Research workbench UI layered onto the existing diagnostic dashboard."""
STYLE=r'''
.lab-layout>*{min-width:0}.lab-layout section,.lab-layout .card{min-width:0}.lab-fields-section h3{gap:12px;flex-wrap:wrap}header{flex-wrap:wrap;gap:12px}@media(max-width:700px){.lab-fields-section h3 small{display:block;font-size:11px;margin-top:8px}.lab-layout{width:100%}.lab-result .card b{font-size:17px}}
header{padding:20px 30px}h1{font-size:20px}.subtitle{margin-top:6px}.workbench-intro{display:flex;justify-content:space-between;gap:24px;align-items:start;margin-bottom:22px}.eyebrow{color:var(--cyan);font-size:11px;letter-spacing:.15em;text-transform:uppercase}.workbench-intro h2{font-size:27px;margin:8px 0}.workbench-intro p{color:var(--muted);max-width:720px;line-height:1.7;margin:0}.pill{border:1px solid var(--border);padding:7px 10px;border-radius:20px;color:var(--muted);white-space:nowrap}.lab-layout{display:grid;grid-template-columns:260px minmax(0,1fr);gap:18px}.lab-sidebar{margin:0;height:max-content}.lab-sidebar label{display:block;margin:16px 0 8px}.lab-sidebar select{width:100%}.lab-sidebar button{width:100%;margin-top:10px}.lab-toolbar{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.primary{background:#145650;border-color:#26796d;color:#d9fffa}.danger{color:var(--red)}.field-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.lab-field{min-width:0;display:grid;gap:7px}.lab-field span{font-size:12px;color:var(--muted);line-height:1.4}.lab-field small{font-size:10px;color:#a8906b}input,select,textarea{font:inherit;background:#0b1520;color:var(--text);border:1px solid #34485b;border-radius:5px;padding:10px;width:100%;min-width:0}input:focus,select:focus,textarea:focus{outline:2px solid var(--cyan);outline-offset:1px}input[type=checkbox]{width:18px;height:18px;margin:9px 0}input:disabled,select:disabled{color:#a8b6c2;background:#14202b}button:disabled{opacity:.5;cursor:not-allowed}.lab-message{line-height:1.7;color:var(--muted);margin:16px 0}.lab-fields-section{margin:0 0 16px}.lab-fields-section h3{display:flex;justify-content:space-between}.lab-replay{margin-top:18px;border-top:1px solid var(--border);padding-top:18px}.lab-replay p{color:var(--muted);line-height:1.6}.lab-replay input{max-width:450px}.live-status{display:flex;gap:12px;align-items:center;justify-content:space-between}.live-status h2{font-size:26px;margin-top:8px}.source-strip{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-bottom:18px}.source-strip section{margin:0}.source-strip b{display:block;margin:7px 0;font-size:18px}.source-strip p{color:var(--muted);font-size:12px;line-height:1.6}.lab-result{margin-top:16px}.lab-result table{font-size:12px}@media(max-width:1000px){.field-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.lab-layout{grid-template-columns:220px minmax(0,1fr)}}@media(max-width:700px){.lab-layout{grid-template-columns:1fr}.field-grid{grid-template-columns:1fr 1fr}.source-strip{grid-template-columns:1fr}.workbench-intro{display:block}.workbench-intro .pill{display:inline-block;margin-top:12px}.live-status{display:block}}
'''

SCRIPT=r'''
let labCatalog=null,labProfile=null,labDirty=false,labInitialized=false,labClock=null,labClockRequested=0,labRuns=null,labRunsLoaded=false,labRunsBusy=false,labSavedRun=null;
async function labRequest(url,body){const r=await fetch(url,body===undefined?{cache:'no-store'}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const d=await r.json();if(!r.ok){const help={LAB_RESOURCE_OR_CAUSAL_LIMIT:'Use a 1–299 second horizon, book age ≤ 2 s, 100–2,000 model paths, ≤ 10,000 shares and delay/gap ≤ 10 s.',LAB_REVISION_CONFLICT:'This strategy changed in another tab. Reload its saved version before editing.',LAB_LOW_DISK_GUARD:'Replay stopped: the project and temporary drive must each have at least 8 GiB free.',LAB_INVALID_CONFIGURATION_OR_INPUT:'Check the parameter types and ranges; the configuration was not saved.',LAB_SAME_ORIGIN_REQUIRED:'Strategy changes are available only from this local dashboard.',LAB_REPLAY_BUSY:'Another offline replay is running. Wait for it to finish.'};throw Error(help[d.error]||d.error||'Request failed')}return d}
const fieldTitle=k=>k.replaceAll('_',' ').replace(/^./,s=>s.toUpperCase());
function labMessage(message,error=false){$('labMessage').textContent=message;$('labMessage').className='lab-message '+(error?'bad':'')}
function markLabDirty(){labDirty=true;$('labRun').disabled=true;labMessage('Unsaved changes · Save a version before replay or export. Live data updates will preserve your edits.')}
function labFields(values,schema,group){return Object.entries(values).map(([key,value])=>{let p=schema.properties?.[key]||{};if(p.$ref)p=schema.$defs?.[p.$ref.split('/').pop()]||p;const locked=group==='common'&&Object.hasOwn(labCatalog.locked_common,key);const id='lab_'+group+'_'+key;
 let control=p.enum?'<select id="'+id+'" '+(locked?'disabled':'')+'>'+p.enum.map(v=>'<option value="'+esc(v)+'" '+(v===value?'selected':'')+'>'+esc(fieldTitle(v))+'</option>').join('')+'</select>':typeof value==='boolean'?'<input id="'+id+'" type="checkbox" '+(value?'checked':'')+'>':'<input id="'+id+'" type="'+(typeof value==='number'?'number':'text')+'" step="'+(p.type==='integer'?'1':'any')+'" value="'+esc(value)+'" '+(locked?'disabled':'')+'>';
 return '<label class="lab-field" for="'+id+'"><span>'+esc(fieldTitle(key))+'</span>'+control+(locked?'<small>Fixed by this causal replay engine</small>':'')+'</label>'}).join('')}
function showLabProfile(profile){labProfile=profile;labDirty=false;$('labName').value=profile.name;$('labFamily').value=profile.config.strategy_family;
 $('labCommon').innerHTML=labFields(profile.config.common,labCatalog.common_schema,'common');$('labParams').innerHTML=labFields(profile.config.params,labCatalog.parameter_schemas[profile.config.strategy_family],'params')||'<p class="muted">This family uses the common edge and execution settings.</p>';
 for(const group of ['common','params'])for(const key of Object.keys(profile.config[group]))$('lab_'+group+'_'+key).oninput=markLabDirty;
 $('labArchive').disabled=profile.frozen;$('labRun').disabled=false;$('labRevision').textContent=(profile.frozen?'Frozen preset · clone to edit':'Saved revision '+profile.revision)+' · '+profile.config_sha256.slice(0,12);
 labMessage(profile.frozen?'Preset loaded. Saving creates your own version; historical benchmarks stay intact.':'Saved definition loaded. Changes create a new immutable revision.')}
async function loadLabProfiles(preferred){const d=await labRequest('/api/lab/strategies');if(!d.profile_policy_revision)throw Error('Strategy catalog unavailable');labCatalog=d;
 $('labSelect').innerHTML=d.strategies.map(p=>'<option value="'+esc(p.strategy_id)+'">'+esc((p.frozen?'PRESET · ':'MY STRATEGY · ')+p.name)+'</option>').join('');
 $('labFamily').innerHTML=Object.entries(d.parameter_schemas).map(([key])=>'<option value="'+esc(key)+'">'+esc(fieldTitle(key))+'</option>').join('');
 const selected=d.strategies.find(p=>p.strategy_id===preferred)||d.strategies[0];$('labSelect').value=selected.strategy_id;showLabProfile(selected)}
function readLabConfig(){const cfg=structuredClone(labProfile.config);cfg.strategy_family=$('labFamily').value;
 for(const group of ['common','params'])for(const [key,value] of Object.entries(cfg[group])){const n=$('lab_'+group+'_'+key);cfg[group][key]=typeof value==='boolean'?n.checked:typeof value==='number'?Number(n.value):n.value;if(typeof value==='number'&&!Number.isFinite(cfg[group][key]))throw Error('Invalid number: '+fieldTitle(key))}return cfg}
async function saveLabProfile(copy=false){try{if(!labProfile)throw Error('Load a preset first');const body={name:$('labName').value,config:readLabConfig()};if(!copy&&!labProfile.frozen){body.strategy_id=labProfile.strategy_id;body.expected_revision=labProfile.revision}const saved=await labRequest('/api/lab/strategies',body);await loadLabProfiles(saved.strategy_id);labMessage('Saved revision '+saved.revision+'. Previous revisions and experiment results are preserved.')}catch(e){labMessage(e.message,true)}}
function labDownload(value,name){const blob=new Blob([JSON.stringify(value,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function runLabReplay(){if(labDirty){labMessage('Save your changes before running replay.',true);return}const file=$('labReplayFile').files[0];if(!file){labMessage('Choose a curated replay JSONL file. This does not start a collector.',true);return}if(file.size>2000000){labMessage('Replay input exceeds 2 MB.',true);return}
 $('labRun').disabled=true;labMessage('Running an isolated shadow replay against the saved definition…');
 try{const result=await labRequest('/api/lab/replay',{strategy_id:labProfile.strategy_id,revision:labProfile.revision,input_jsonl:await file.text()});const rounds=result.research_rounds||[],settled=rounds.filter(r=>r.pnl!==null),pnl=settled.reduce((s,r)=>s+Number(r.pnl),0),fees=(result.fills||[]).reduce((s,r)=>s+Number(r.fee),0);
 $('labResult').innerHTML=cards([['Coverage',result.status==='SUPPORTED_SYNTHETIC_OR_CURATED'?'Supported inputs':'Missing inputs'],['Shadow fills',String(result.fills.length)],['Fees',money(fees)],['Settled net PnL',settled.length?money(pnl):'Unresolved']])+block('Execution results',table(result.fills,[['strategy','Strategy'],['at_us','Execution UTC µs'],['outcome','Side'],['shares','Filled shares'],['notional','Cost'],['fee','Fee']]))+block('Missing inputs and rejections',details({unsupported:result.unsupported_reasons,coverage:result.research_coverage,orders:result.orders}))+block('Frozen run provenance',details({run_id:result.run_id,profile:result.profile,policies:result.policies,settlement:rounds,source_authentication:result.source_authentication}));
 $('labResultDownload').disabled=false;$('labResultDownload').onclick=()=>labDownload(result,'btc-lab-run-'+result.run_id+'.json');labMessage('Replay saved to Results. Unsettled outcomes are not reported as profits.');labSavedRun=result;await loadLabRuns();
 }catch(e){labMessage(e.message,true)}finally{$('labRun').disabled=labDirty}}
function ensureWorkbench(){if(labInitialized)return;labInitialized=true;
 $('view1').innerHTML='<div class="workbench-intro"><div><span class="eyebrow">Build · Freeze · Test</span><h2>Strategies</h2><p>Design and compare BTC five-minute strategies against recorded observations. Save every parameter, run causal replay, and inspect the fills that were actually possible.</p></div><span class="pill">No live orders · No collector launch</span></div><div class="lab-layout"><section class="lab-sidebar"><h3>Your strategy library</h3><label for="labSelect">Load a preset or saved strategy</label><select id="labSelect"></select><button id="labCopy">Save as new strategy</button><button id="labArchive" class="danger">Archive strategy</button><p class="muted">Archiving removes a custom strategy from the library. Earlier versions and test results remain available.</p><hr><p class="muted">BOOK_CONFIRM_75 and historical benchmark signal rules remain frozen.</p></section><div><section class="lab-fields-section"><div class="lab-toolbar"><span class="eyebrow">Definition</span><span id="labRevision" class="muted"></span></div><div class="field-grid" style="margin-top:16px"><label class="lab-field" for="labName"><span>Strategy name</span><input id="labName" maxlength="64"></label><label class="lab-field" for="labFamily"><span>Signal family</span><select id="labFamily"></select></label></div></section><section class="lab-fields-section"><h3>Decision & execution parameters <small>Source and receipt age ≤ 2 seconds</small></h3><div id="labCommon" class="field-grid"></div></section><section class="lab-fields-section"><h3>Signal parameters</h3><div id="labParams" class="field-grid"></div></section><div class="lab-toolbar"><button id="labSave" class="primary">Save version</button><button id="labExport">Export saved definition</button></div><p id="labMessage" role="status" aria-live="polite" class="lab-message">Loading strategy definitions…</p><section class="lab-replay"><h3>Test against a recorded window</h3><p>Upload curated replay JSONL with market identity, source/receipt/processing clocks, depth, fees and model inputs. Missing evidence produces an explicit unavailable result. Maximum 2 MB / 5,000 events / 30 minutes.</p><label class="lab-field" for="labReplayFile"><span>Replay JSONL file</span><input id="labReplayFile" type="file" accept=".jsonl"></label><div class="lab-toolbar" style="margin-top:16px"><button id="labRun" class="primary">Run offline replay</button><button id="labResultDownload" disabled>Download run report</button></div><p class="muted">Every completed run is saved in Results, including its frozen strategy definition.</p><button id="labGoResults">View saved results</button><div id="labResult" class="lab-result"></div></section></div></div>';
 $('labSelect').onchange=()=>showLabProfile(labCatalog.strategies.find(p=>p.strategy_id===$('labSelect').value));$('labName').oninput=markLabDirty;
 $('labFamily').onchange=()=>{const cfg=structuredClone(labProfile.config);cfg.strategy_family=$('labFamily').value;cfg.params=structuredClone(labCatalog.strategies.find(p=>p.config.strategy_family===cfg.strategy_family).config.params);showLabProfile({...labProfile,config:cfg});markLabDirty()};
 $('labSave').onclick=()=>saveLabProfile(false);$('labCopy').onclick=()=>saveLabProfile(true);
 $('labArchive').onclick=async()=>{try{await labRequest('/api/lab/strategies/archive',{strategy_id:labProfile.strategy_id,expected_revision:labProfile.revision});await loadLabProfiles();labMessage('Custom strategy archived. Historical versions and runs are preserved.')}catch(e){labMessage(e.message,true)}};
 $('labExport').onclick=()=>{if(labDirty){labMessage('Save changes before exporting the frozen definition.',true);return}labDownload(labProfile,'btc-strategy-'+labProfile.strategy_id+'-v'+labProfile.revision+'.json')};$('labRun').onclick=runLabReplay;$('labGoResults').onclick=()=>selectTab(2);
 loadLabProfiles().catch(e=>labMessage(e.message,true));}
function renderLabRuns(){
 const list=$('labRunsList');if(!list)return;
 if(!labRuns){list.innerHTML='<p class="empty">'+(labRunsBusy?'Loading saved runs…':'Open this tab to load your saved replay runs.')+'</p>';return}
 list.innerHTML=(labRuns.runs.length?'<div class="scroll"><table><thead><tr><th>Strategy / revision</th><th>Dataset</th><th>Coverage</th><th>Fills</th><th>Settled / unresolved</th><th>Net settled PnL</th><th>Report</th></tr></thead><tbody>'+labRuns.runs.map(r=>'<tr><td>'+esc(r.name)+' · v'+esc(r.revision)+'</td><td>'+esc(r.dataset)+'</td><td>'+esc(r.status==='SUPPORTED_SYNTHETIC_OR_CURATED'?'Supported inputs':'Missing inputs')+'</td><td>'+esc(r.fills)+'</td><td>'+esc(r.settled_markets)+' / '+esc(r.unsettled_markets)+'</td><td>'+esc(r.settled_net_pnl===null?'Unresolved':money(r.settled_net_pnl))+'</td><td><button class="lab-open-run" data-run="'+esc(r.run_id)+'">Inspect</button></td></tr>').join('')+'</tbody></table></div>':'<p class="empty">No saved replay runs yet. Choose a strategy and test a recorded window in Strategies.</p>')+(labRuns.limited?'<p class="muted">Showing a bounded selection of the latest runs (20 reports / 4 MB maximum).</p>':'')+(labRuns.errors?.length?'<p class="bad">'+esc(labRuns.errors.join(' · '))+'</p>':'');
 list.querySelectorAll('.lab-open-run').forEach(button=>button.onclick=async()=>{try{labSavedRun=await labRequest('/api/lab/runs?run_id='+encodeURIComponent(button.dataset.run));renderSavedRun()}catch(e){$('labSavedDetail').textContent=e.message}});renderSavedRun();
}
function renderSavedRun(){if(!labSavedRun)return;const result=labSavedRun;
 $('labSavedDetail').innerHTML=block('Selected run · '+result.profile.name+' · revision '+result.profile.revision,'<p class="muted">'+esc(result.run_id)+' · Source authenticity is caller supplied. Missing observations are never reconstructed as fills.</p><button id="labSavedDownload">Download full report</button>'+table(result.fills,[['strategy','Strategy'],['at_us','Execution UTC µs'],['outcome','Side'],['shares','Filled shares'],['notional','Cost'],['fee','Fee']])+'<details><summary>Definition, coverage and execution provenance</summary>'+details({profile:result.profile,manifest:result.manifest,policies:result.policies,coverage:result.research_coverage,missing:result.unsupported_reasons,orders:result.orders,settlement:result.research_rounds})+'</details>');
 $('labSavedDownload').onclick=()=>labDownload(result,'btc-lab-run-'+result.run_id+'.json');
}
async function loadLabRuns(){if(labRunsBusy)return;labRunsBusy=true;renderLabRuns();try{labRuns=await labRequest('/api/lab/runs');labRunsLoaded=true}catch(e){labRuns={runs:[],errors:[e.message]}}finally{labRunsBusy=false;renderLabRuns()}}
const originalRender=render;
render=function(d){originalRender(d);ensureWorkbench();renderLabRuns();$('labRefreshRuns').onclick=()=>loadLabRuns();const diag=d.diagnostics||{},book=diag.book?.health||diag.book||{},sample=d.sample||{};
 if(Date.now()-labClockRequested>60000){labClockRequested=Date.now();labRequest('/api/lab/clock').then(s=>{labClock=s;if($('labHostClock'))$('labHostClock').textContent=s.state==='SERVICE_REPORTS_SYNCHRONIZED'?'Host time service synchronized':'Host UTC synchronization not verified'}).catch(()=>{labClock={state:'UNVERIFIED'}})}
 const sampleAge=Number.isFinite(sample.sample_ts_us)?(d.observed_at_us-sample.sample_ts_us)/1e6+(d.cache_age_seconds||0):Infinity;
 const fresh=diag.observation_state==='CURRENT_OBSERVATION'&&sample.market_is_current&&sampleAge>=0&&sampleAge<=2;const status=!fresh?'Historical / stale or waiting sample':labClock?.state!=='SERVICE_REPORTS_SYNCHRONIZED'?'Clock synchronization required':sample.state==='READY'?'Latest sample: FULL READY':'Waiting for required inputs';
 const head='<section class="live-status"><div><span class="eyebrow">Live data monitor</span><h2>'+esc(status)+'</h2><p class="muted">'+esc(sample.unavailable_reason||'Model, source clocks and order-book checks remain independent.')+'</p><small id="labHostClock">'+esc(labClock?.state==='SERVICE_REPORTS_SYNCHRONIZED'?'Host time service synchronized':'Host UTC synchronization not verified')+'</small></div><span class="pill">Research data · Shadow execution</span></section>';
 const strip='<div class="source-strip">'+[['Polymarket CLOB',d.feeds?.find(f=>f.component==='polymarket_clob')?.observation_state||'No current observation','UP / DOWN depth must be coherent. Recent delivery cannot refresh an old source timestamp.'],['Coinbase + Kraken',diag.sources?.length?diag.sources.map(s=>s.source+': '+s.state).join(' · '):'Reference history unavailable','Source-trade freshness is checked independently of network receipt and heartbeats.'],['Official price to beat',diag.reference?.state||'Unavailable','A retained market reference does not make the model or execution ready.']].map(([title,state,body])=>'<section><span class="eyebrow">'+esc(title)+'</span><b>'+esc(state)+'</b><p>'+esc(body)+'</p></section>').join('')+'</div>';
 $('view0').innerHTML=head+strip+$('view0').innerHTML;};
'''
